package com.sih.portal.config; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.*; import org.springframework.security.config.annotation.web.configurers.*; import org.springframework.security.web.*; @Configuration @Profile({"mock","default","secure"}) public class SecurityConfig{@Bean SecurityFilterChain c(HttpSecurity h)throws Exception{return h.csrf(AbstractHttpConfigurer::disable).authorizeHttpRequests(a->a.anyRequest().permitAll()).build();}}